import{_ as s,o as e,c as n,a5 as i}from"./chunks/framework.BPFk9-tb.js";const g=JSON.parse('{"title":"使用Gradle生成BOM管理依赖","description":"","frontmatter":{"date":"2021-05-15T13:12:08","title":"使用Gradle生成BOM管理依赖","categories":["Gradle"],"tags":["Gradle"]},"headers":[{"level":2,"title":"什么BOM","slug":"什么bom","link":"#什么bom","children":[]},{"level":2,"title":"Gradle","slug":"gradle","link":"#gradle","children":[]},{"level":2,"title":"要点说明","slug":"要点说明","link":"#要点说明","children":[{"level":3,"title":"引入插件","slug":"引入插件","link":"#引入插件","children":[]},{"level":3,"title":"申明api或runtime约束","slug":"申明api或runtime约束","link":"#申明api或runtime约束","children":[]},{"level":3,"title":"使用第三方BOM","slug":"使用第三方bom","link":"#使用第三方bom","children":[]},{"level":3,"title":"发布","slug":"发布","link":"#发布","children":[]},{"level":3,"title":"引入BOM","slug":"引入bom","link":"#引入bom","children":[]}]}],"relativePath":"posts/java/gradle-002.md","filePath":"posts/java/gradle-002.md"}'),l={name:"posts/java/gradle-002.md"};function p(t,a,o,r,d,c){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h2 id="什么bom" tabindex="-1">什么BOM <a class="header-anchor" href="#什么bom" aria-label="Permalink to &quot;什么BOM&quot;">​</a></h2><p>BOM (The Bill of Materials in Maven) 是Maven中的概念，是一个 pom.xml 文件，主要用来管理项目的依赖版本、插件等构建配置信息。其它项目可以在使用 BOM 时，无需定义已在 BOM 中定义依赖的版本号，即可获取版本号，可理解为统一依赖版本的用途。</p><h2 id="gradle" tabindex="-1">Gradle <a class="header-anchor" href="#gradle" aria-label="Permalink to &quot;Gradle&quot;">​</a></h2><p>Gradle被认为是更好的Maven替代，但在BOM的支持上不是太友好，管理多模块项目就会使用难度。我自己就在这个多模块管理被耽误的。实际上，Gradle 6开始可以通过<a href="https://docs.gradle.org/current/userguide/java_platform_plugin.html" target="_blank" rel="noreferrer">java-platform</a>插件定义和发布BOM文件。这样完全可以只通过Gradle就靠可以管理多模块项目。</p><h2 id="要点说明" tabindex="-1">要点说明 <a class="header-anchor" href="#要点说明" aria-label="Permalink to &quot;要点说明&quot;">​</a></h2><p>以下的操作都是在项目的<code>build.gradle</code>进行。</p><h3 id="引入插件" tabindex="-1">引入插件 <a class="header-anchor" href="#引入插件" aria-label="Permalink to &quot;引入插件&quot;">​</a></h3><div class="language-groovy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">groovy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plugins {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;java-platform&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>注意</strong> java-platform不能与java插件一起使用。</p><h3 id="申明api或runtime约束" tabindex="-1">申明api或runtime约束 <a class="header-anchor" href="#申明api或runtime约束" aria-label="Permalink to &quot;申明api或runtime约束&quot;">​</a></h3><div class="language-groovy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">groovy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dependencies {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    constraints {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        api </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;commons-httpclient:commons-httpclient:3.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        runtime </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;org.postgresql:postgresql:42.2.5&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>###将约束转为依赖</p><p>默认情况下，constraions只是申明了版本关系，并不是依赖关系，如果需要引入为依赖关系，需要做如下的指定：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>javaPlatform {</span></span>
<span class="line"><span>    allowDependencies()</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="使用第三方bom" tabindex="-1">使用第三方BOM <a class="header-anchor" href="#使用第三方bom" aria-label="Permalink to &quot;使用第三方BOM&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dependencies {</span></span>
<span class="line"><span>    api platform(&#39;com.fasterxml.jackson:jackson-bom:2.9.8&#39;)</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to &quot;发布&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>publishing {</span></span>
<span class="line"><span>    publications {</span></span>
<span class="line"><span>        myPlatform(MavenPublication) {</span></span>
<span class="line"><span>            from components.javaPlatform</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="引入bom" tabindex="-1">引入BOM <a class="header-anchor" href="#引入bom" aria-label="Permalink to &quot;引入BOM&quot;">​</a></h3><p>在其他项目中通过<code>api flatform</code>的方式引入BOM，具体引入某个依赖包时就可以不指定版本号。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dependencies {</span></span>
<span class="line"><span>    // get recommended versions from the platform project</span></span>
<span class="line"><span>    api platform(project(&#39;:platform&#39;))</span></span>
<span class="line"><span>    // no version required</span></span>
<span class="line"><span>    api &#39;commons-httpclient:commons-httpclient&#39;</span></span>
<span class="line"><span>}</span></span></code></pre></div><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>`,28)])])}const m=s(l,[["render",p]]);export{g as __pageData,m as default};
